fn main() {
    let mut out: Vec<serde_json::Value> = Vec::new();
    dump_base(&mut out);
    dump_ninja(&mut out);
    dump_cowboy(&mut out);
    dump_wizard(&mut out);
    dump_robot(&mut out);
    dump_mutant(&mut out);
    dump_grappling_hook(&mut out);
    dump_heavy_whip_wave(&mut out);
    dump_heavy_whip_wave_high(&mut out);
    dump_whip_wave(&mut out);
    dump_after_image(&mut out);
    dump_spark_bomb(&mut out);
    dump_telekinesis_boulder(&mut out);
    dump_vile_clutch(&mut out);
    dump_ground_fire_loic(&mut out);
    dump_ground_fire(&mut out);
    dump_orbital_strike(&mut out);
    dump_robot_grenade(&mut out);
    dump_missile(&mut out);
    dump_poison(&mut out);
    dump_caustic_spike(&mut out);
    dump_gas_bomb(&mut out);
    dump_shockwave(&mut out);
    for v in out {
        println!("{}", v);
    }
}
